 156	        // normally snapshots this after preludes run, which would otherwise make
 157	        // `mise deactivate` restore mise's own shim farms.
 158	        if env::__MISE_ORIG_PATH.is_none() {
 159	            let path = std::env::join_paths(&*env::PATH)
