    #[usage(long, value_name = "TOOL", aliases = ["rm", "unset"])]
    remove: Vec<BackendArg>,
}

#[derive(Debug, usage_rs::Args)]
struct UseTool {
    /// Command to run after installing this tool
    #[usage(long, value_name = "COMMAND")]
